            if grid[r][c] != bg:
                points.setdefault(grid[r][c], []).append((r, c))

    for color, cells in points.items():
        s = set(cells)
        # Find diagonal runs; extend their ends only when the surrounding
        # pattern indicates a ray, rather than a compact two-color marker.
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in cells:
                if (r-dr, c-dc) in s:
                    continue
                run = []
                rr, cc = r, c
                while (rr, cc) in s:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # The ray points away from the nearby colored structure.
                # Test each end; avoid extending into compact marker motifs.
                for er, ec, sr, sc in (
                    (run[0][0], run[0][1], -dr, -dc),
                    (run[-1][0], run[-1][1], dr, dc),
                ):
                    rr, cc = er + sr, ec + sc
                    if not (0 <= rr < h and 0 <= cc < w):
                        continue
                    nearby = [(r0, c0) for r0, row in enumerate(grid)
                              for c0, v in enumerate(row)
                              if v != bg and v != color
                              and abs(r0-er) <= 1 and abs(c0-ec) <= 1]
                    if nearby:
                        continue
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
